params.command:
$ErrorActionPreference='Continue'
$repo='C:\Users\Xxkan\mhw-safe-branch-delete'
if(-not (Test-Path (Join-Path $repo '.git'))){ throw "missing repo $repo" }
git -C $repo fetch origin --prune
if($LASTEXITCODE -ne 0){ throw "fetch failed $LASTEXITCODE" }
$branches = git -C $repo for-each-ref --format='%(refname:strip=3)' refs/remotes/origin | Where-Object { $_ -and $_ -notin @('HEAD','main','heaven-bridge') -and $_ -ne 'origin' } | Sort-Object -Unique
$deleted=@(); $kept=@(); $failed=@()
foreach($b in $branches){
  git -C $repo merge-base --is-ancestor ("origin/"+$b) origin/main 2>$null
  $ancestor = ($LASTEXITCODE -eq 0)
  $patchEquivalent = $false
  if(-not $ancestor){
    $cherry = @(git -C $repo cherry origin/main ("origin/"+$b) 2>$null)
    if($LASTEXITCODE -eq 0){
      $plus = @($cherry | Where-Object { $_ -match '^\+' })
      $patchEquivalent = ($plus.Count -eq 0)
    }
  }
  if($ancestor -or $patchEquivalent){
    & git -C $repo push origin --delete $b 2>&1 | Out-Host
    if($LASTEXITCODE -eq 0){ $deleted += $b } else { $failed += $b }
  } else {
    $kept += $b
  }
}
git -C $repo fetch origin --prune | Out-Null
$remaining = @(git -C $repo for-each-ref --format='%(refname:strip=3)' refs/remotes/origin | Where-Object { $_ -and $_ -notin @('HEAD','main','heaven-bridge') -and $_ -ne 'origin' } | Sort-Object -Unique)
[pscustomobject]@{
  main=(git -C $repo rev-parse origin/main)
  deleted_count=$deleted.Count
  deleted=$deleted
  kept_unique_count=$kept.Count
  kept_unique=$kept
  failed_count=$failed.Count
  failed=$failed
  disposable_remaining_count=$remaining.Count
  remaining=$remaining
} | ConvertTo-Json -Depth 5
